"""Assemble the scope and frozen Gate 3 decision after all mandatory co-primary replay."""
from grid import *
import pandas as pd
import platform
from analyze import table as tabs
def finalize():
    guard();dest=root3/'results';L=json.loads((dest/'native_primary.json').read_text());corr=json.loads((dest/'structure_summary.json').read_text());cross=json.loads((dest/'transition_summary.json').read_text())
    rs=pd.read_csv(dest/'sensitivity_summary.csv');u=pd.read_csv(dest/'uncertainty_summary.csv');oracle=pd.read_csv(dest/'oracle_summary.csv');exact=pd.read_csv(dest/'exact_two.csv')
    cal=pd.read_csv(dest/'calibration_size.csv');phase=pd.read_csv(dest/'phase_summary.csv');net=pd.read_csv(dest/'net_summary.csv');tim=pd.read_csv(dest/'times.csv');decision=pd.read_csv(dest/'block_decisions.csv')
    spatial=pd.read_csv(root3/'ray_manifest.csv');ab=tabs(dest/'ablations','*.csv');ab.groupby(['mode','family']).agg(median_G=('G','median'),n=('G','size')).to_csv(dest/'ablation_summary.csv')
    # Merge all controls without deleting block failures or replacing outcomes.
    controls=[]
    for group in ['native','analytic','ray']:
        c=tabs(dest/('controls_'+group),'*.csv');expect={'native':18432,'analytic':18432,'ray':4608}[group];assert len(c)==expect,(group,len(c),expect)
        controls.append(c.assign(campaign=group))
    cc=pd.concat(controls);cc.groupby(['campaign','family','k','db','method']).agg(n=('G','size'),G=('G','median'),L=('L','median'),U=('U','median'),ms=('ms','median')).to_csv(dest/'classical_summary.csv')
    # Native unit is the topology, with common block IDs across every method, SNR and user count.
    q=tim.groupby(['k','method']).agg(p95_ms=('total_ns',lambda x:x.quantile(.95)/1e6),median_ms=('total_ns',lambda x:x.median()/1e6),gpu_p95=('gpu_ms',lambda x:x.quantile(.95))).reset_index()
    load=pd.read_csv(dest/'load_sensitivity.csv');s=load.merge(tim.groupby(['family','block','k','method'],as_index=False).total_ns.median(),on=['family','block','k','method'],suffixes=('_shuffled','_original'));assert len(s)==416
    s['ratio']=s.total_ns_shuffled/s.total_ns_original;s.groupby(['k','method']).ratio.agg(['size','median','min','max']).to_csv(dest/'load_summary.csv')
    paired=decision.pivot(index=['family','block','k'],columns='method',values=['G','ms']);ratios=s[s.method=='det'].groupby('k').ratio.median()
    costs=net[(net.H==1024)&(net.M==0)];mx=corr['posterior'];pri=corr['prior'];a=f"{mx['rho']:.3f} (95% interval {mx['ci'][0]:.3f}–{mx['ci'][1]:.3f})";b=f"{pri['rho']:.3f} ({pri['ci'][0]:.3f}–{pri['ci'][1]:.3f})"
    matrix=tabs(dest/'matrix_methods','*.csv');expected=3*(13824-512*2)
    assert len(matrix)==expected and not matrix.duplicated(['family','block','k','db','method']).any(),(len(matrix),expected)
    aa=tim[(tim.rep==0)&tim.method.isin(['legacy','standalone','hybrid'])].rename(columns={'Lbit':'L','Ubit':'U'});aa=aa.assign(component_ms=aa.total_ns/1e6)
    mm=pd.concat([matrix,aa[matrix.columns]],ignore_index=True);assert len(mm)==3*13824
    mm.groupby(['family','k','db','method']).agg(n=('G','size'),median_G=('G','median'),median_L=('L','median'),median_U=('U','median'),median_component_ms=('component_ms','median')).to_csv(dest/'paired_matrix_summary.csv')
    import scipy,numba,networkx,datetime
    train_s=sum(json.loads((home/'results'/f'seed_{s}.json').read_text())['seconds'] for s in evaluate.seeds)
    start=datetime.datetime.fromisoformat(json.loads((home/'results/gate2b_lock.json').read_text())['utc'])
    end=datetime.datetime.now(datetime.timezone.utc);wall_h=(end-start).total_seconds()/3600
    sizes=sum(p.stat().st_size for p in root3.rglob('*') if p.is_file())
    budget=dict(measured_at=end.isoformat(),GPU_training_seconds=train_s,elapsed_gate3_hours_including_acquisition_and_summaries=wall_h,gate3_retained_bytes=sizes,limits=dict(gpu_training_hours=24,elapsed_hours=120,scratch_GB=500),software=dict(python=platform.python_version(),numpy=np.__version__,scipy=scipy.__version__,numba=numba.__version__,networkx=networkx.__version__),processor=platform.processor(),platform=platform.platform(),measurement_scope='retained bytes, not peak disk occupancy; crop/serialization included in sensitivity details')
    writej(dest/'budget.json',budget)
    text=[]
    text.append(f"Confirmatory scope. All 512 native topologies were held out at selection. The Gate 2B lock links back to the pre-pilot freeze. Both primary targets {'passed' if L['pass'] else 'did not pass'} their point-estimate and one-sided confidence rules. Hierarchical learning {'passed' if L['hierarchical_learning'] else 'did not pass'} the +10 percentage-point threshold at 32 users with a positive lower limit and no sign reversal at 64. The unchanged batch-one GPU hardware does not establish a <2 ms forward p95.")
    text.append(f"Timing sensitivity. The 52 prespecified native blocks contributed all 416 extra calls in randomized order. For deterministic polish the median shuffled/original per-block time ratio was {ratios.loc[32]:.2f} at 32 users and {ratios.loc[64]:.2f} at 64. Other simulation jobs shared the host; these are workstation end-to-end measurements. The archive gives every repeat and the original hashes; no deadline result was reassigned after this check.")
    text.append(f"Independent geometry and controls. Tested 512 analytic seed/family units, 512 native topology units, and {len(spatial)} guarded ray tiles ({', '.join(f'{k}: {v}' for k,v in spatial.groupby('scene').size().items())}); 13,824 known-channel grid cells at four SNRs and three user counts. Three additional paired classical policies contributed {len(cc):,} controls, including unchanged power and sequential pairs, equal-power matching/Hungarian plus local power search, and cold prices. Ray results are within-scene, one real BS each. The orthogonal analytic condition means orthogonal scheduled pairs; only sixteen mutually orthogonal nonzero vectors fit the 16-element array.")
    text.append(f"Cross-grid comparison: {len(mm):,} single-shot, learned-warm and resource-subgradient method/cell combinations. The confirmatory native operating points use separate end-to-end clocks. Outside them the three alternatives share a proposal for paired interval-quality analyses, so their component-assembled times are descriptive.")
    text.append(f"Compute reserve: {train_s/3600:.3f} aggregate GPU training hours across three seeds, {wall_h:.2f} elapsed workstation hours from the pilot lock through campaign analysis, and {sizes/1e9:.2f} GB retained in the Gate 3 tree (not peak scratch). The time reserves were 24 GPU training hours and 120 elapsed workstation hours.")
    text.append(f"Structural result. Exact integer labelled DP on the matching’s own table gave posterior conflict versus relaxation loss Spearman {a}; the prior bound gave {b} (512 native blocks, 16 users, 10 dB). The posterior cleared the predeclared 0.30 lower-limit bar. The 128 frequency-selective seeds, nine grid points, and fixed equal-power/sequential actions gave no sustained 50% crossing; {100*cross['bootstrap_no_cross_fraction']:.1f}% of whole-seed bootstrap replicates had none. This is not evidence of a universal phase transition.")
    text.append(f"Small-instance references. The independent rational two-user root isolation reached the 1e-6 bit/s/Hz goal on {len(exact)}/{len(exact)} cases (maximum width {exact.G_oracle.max():.2g}). Exhaustive labelled schedules plus bounded continuous box search at 4, 6, 8 users attained it on {int(oracle[oracle.k>2].resolved.sum())}/{int(oracle[oracle.k>2].n.sum())}. The unresolved boxes, tested incumbents, 192-split cap and numerical widths are published. They do not establish ground-truth tightness at those sizes; no separating-oracle claim is made for them.")
    for fam in ['C','UMa']:
        v=u[(u.family==fam)&(u.db==10)].set_index('arm');text.append(f"Uncertain CSI, {fam}, 32 users at 10 dB. Joint coverage hits: fixed {int(v.loc['fixed','joint'])}/128, scaled {int(v.loc['scaled','joint'])}/128. The positive projected lower bound, gap at most 0.50, retention at least 0.95 and one-second limit held on {int(v.loc['fixed','useful'])}/128 and {int(v.loc['scaled','useful'])}/128 respectively. The one-sided binomial failure flags are {int(v.loc['fixed','coverage_flag'])} and {int(v.loc['scaled','coverage_flag'])}. At n=16, the certified calibration radius is infinite; that vacuous case is retained.")
    text.append("Figures 4 and 5 separate scalar MSE, pilot burden and stationary net utility. We evaluated matched first moments 0.70/0.90 under four phase laws with 16, 64, 256 and 1,024 observed references; the AP-shared control retains cross-tap pseudocovariance and checks augmented PSD. Equal-operator opportunity costs compare warm and cold *actions* on the same estimated CSI with simultaneous projection-score budgets and fixed-action upper/lower intervals. Horizons span 1–1,024 blocks; infeasible reference budgets are marked. The horizon result assumes stationary repeated rates, not physical goodput or a joint guarantee over unobserved future channel changes.")
    text.append("Zero-extra-refresh, H=1,024: the fraction with a strictly positive certified gain was "+'; '.join(f"{r.family}/{r.arm}: {100*r.win:.1f}%" for r in costs.itertuples())+". This uses the prespecified LS control action and is distinct from the known-channel hierarchical comparison to deterministic conflict polish.")
    text.append("Learning and scope. Swaps of primal, resource price, root anchor and priority were run on each native 32-user 10 dB test block with held-fixed components. The training-only one-hidden-layer MLP is an adapted pair classifier with deterministic projection; it is not a reproduction of P1’s published hypergraph or dataset. The existing frozen P2-style CNN is trained on 32 antenna coordinates by two tones. Feeding 16 antennas by a different number of tones into that checkpoint would change feature semantics, so no directly reproduced native CNN performance or universal neural gain is claimed.")
    ota=pd.read_csv(dest/'rice_descriptive.csv');text.append("Rice hardware remains descriptive. At six actual users, the complete accepted HUB and LO chain-A replays had "+' and '.join(f"{r.mode}: {r.success}/{r.postprefix_frames} usable by 250 ms at G ≤ 0.10" for r in ota.itertuples())+". LO misses the 75% hardware target. There is one independently documented acquisition layout per distributed clock; neither RF-chain repeats nor aliases supply twelve independent sessions. The later disjoint LTS is a noisy reference, not true CSI or a field measurement of the proposed pair schedule. F6 uses the accepted full-capture replay; the separate finite-window secondary replay is labelled by RF chain and source directory.")
    if (dest/'rice_field').is_dir():
        capture=sorted((dest/'rice_field').glob('*.csv'));data=pd.concat([pd.read_csv(v) for v in capture],ignore_index=True) if capture else pd.DataFrame()
        if len(data):
            data.groupby(['stratum','k']).agg(windows=('frame','size'),usable=('valid','sum'),useful=('ok','sum'),median_G=('G','median'),active_rf=('active','first')).to_csv(dest/'rice_field_summary.csv');text.append(f"Additional measured check: {len(capture)} catalogue entries yielded {len(data)} nested K=2/4/6 window-size records total. Results use 32 deterministic nonoverlapping frame IDs per recording; they are not new acquisition layouts. Catalogue aliases are not pooled as independent sessions.")
    missing=dest/'rice_field/missing.json'
    if missing.exists():
        for z in json.loads(missing.read_text()):text.append(f"Unscored hardware entry: {z['stratum']}; {z['reason']}. All 32 planned windows at each nested size are abstentions under this fixed calibration rule. No frame was substituted. Recorded payload EVM/BER remains unavailable without a verified transmitted-symbol reference.")
    text.append("Acquisition credit: M. Zafari, Distributed Multi-User MIMO Datasets (IEEE DataPort, DOI 10.21227/74ez-b275), and R. Doost-Mohammady et al., RENEW: Programmable and Observable Massive MIMO Networks (Asilomar 2018, DOI 10.1109/ACSSC.2018.8645391). The release contains acquisition IDs, hashes, metadata and derived metrics only.")
    arg=dest/'argos_summary.json'
    if arg.exists():
        v=json.loads(arg.read_text());text.append('Argos companion spatial check: '+v['statement'])
    else:text.append("No Argos spatial-control values are included in this version. Argos is a separately registered Rice collection and cannot supply the missing distributed HUB/LO replicates.")
    text.append("Inference limits. No Gate 4 independent sign-off or flagship submission is implied. The hardware replication requirement and the larger small-oracle precision target were not met. The strong result is deterministic simulation certification; the full-source audit and statistical tables should accompany any manuscript claim.")
    (root3/'SUPPLEMENT.md').write_text('# Confirmatory interpretation and limitations\n\n'+'\n\n'.join(text)+'\n',encoding='utf8')
    print(L['pass'],L['hierarchical_learning'],len(s),len(cc),flush=True)
if __name__=='__main__':finalize()

